    注意语义边界:这是**引用**证据,不是本表实体证据。
    """
    dom = [("nation", 251), ("comp", 7047), ("club", 84259), ("city", 56293)]
    out = []
    for o in range(0, stride - 3):
        vals = u32(rows, o)
        if any(v == FF for v in vals):
            continue          # 含 FF 说明有 null,不是纯引用列
        for name, lim in dom:
            if all(v < lim for v in vals):
                out.append({"u32_off": o, "domain": name, "domain_size": lim,
                            "distinct": len(set(vals)), "min": min(vals), "max": max(vals),
                            "note": "整列无 null" if 0 not in vals else "含 0(可能是 null 或合法首项)"})
                break
    # 也报"有 null 但非 null 部分全在域内"的列,单独标出
    for o in range(0, stride - 3):
